# Access input coordinates from the global input_data dictionary directly
# as required by the Pokemon Blue execution environment.
import json

x = input_data.get("x", 15)
y = input_data.get("y", 41)

x = int(x)
y = int(y)

buttons = []

# Loop: (15, 41) -> (14, 41) -> (14, 40) -> (15, 40) -> (15, 41)
if (x, y) == (15, 41):
    buttons = ["Left", "Up", "Right", "Down"]
elif (x, y) == (14, 41):
    buttons = ["Up", "Right", "Down", "Left"]
elif (x, y) == (14, 40):
    buttons = ["Right", "Down", "Left", "Up"]
elif (x, y) == (15, 40):
    buttons = ["Down", "Left", "Up", "Right"]
else:
    # Navigate to (15, 41)
    if x < 15:
        buttons.append("Right")
    elif x > 15:
        buttons.append("Left")

    if y < 41:
        buttons.append("Down")
    elif y > 41:
        buttons.append("Up")

print(json.dumps(buttons))
